extends "res://htd/htd_test.gd"

func _run_tests() -> void:
	var rock := instantiate_scene("res://rock.tscn")
	if not check("rock_exists", rock != null, "La scena rock.tscn deve istanziarsi senza errori"):
		return
	var min_x: float = 9999.0
	var max_x: float = -9999.0
	var min_v: float = 9999.0
	var max_v: float = -9999.0
	var min_h: float = 9999.0
	var max_h: float = -9999.0
	for i in range(50):
		call_if_exists(rock, "reset_rock")
		var pos = get_prop(rock, "position", Vector2.ZERO)
		var f_speed = get_prop(rock, "fall_speed", 0.0)
		var h_speed = get_prop(rock, "horizontal_speed", 0.0)
		var dmg = get_prop(rock, "damage", 0)
		var ratio = get_prop(rock, "danger_ratio", 0.0)
		if not check("rock_y", is_equal_approx(pos.y, 80.0), "A ogni reset la roccia deve ripartire da Y = 80.0"):
			return
		if not check("rock_x_bounds", pos.x >= 120.0 and pos.x <= 960.0, "La coordinata X deve rimanere compresa tra 120.0 e 960.0"):
			return
		if not check("fall_bounds", f_speed >= 200.0 and f_speed <= 320.0, "fall_speed deve essere compresa tra 200.0 e 320.0"):
			return
		if not check("h_bounds", h_speed >= -100.0 and h_speed <= 100.0, "horizontal_speed deve essere compresa tra -100.0 e 100.0"):
			return
		if not check("damage_bounds", dmg >= 1 and dmg <= 3, "damage deve essere compreso tra 1 e 3"):
			return
		if not check("ratio_match", is_equal_approx(ratio, float(dmg) / 3.0), "danger_ratio deve corrispondere al rapporto esatto damage / MAX_DAMAGE"):
			return
		if pos.x < min_x: min_x = pos.x
		if pos.x > max_x: max_x = pos.x
		if f_speed < min_v: min_v = f_speed
		if f_speed > max_v: max_v = f_speed
		if h_speed < min_h: min_h = h_speed
		if h_speed > max_h: max_h = h_speed
	check("rock_x_varies", (max_x - min_x) > 200.0, "Le posizioni orizzontali della roccia devono variare nel tempo")
	check("rock_v_varies", (max_v - min_v) > 30.0, "La velocità di caduta deve variare tra discese diverse")
	check("rock_h_varies", min_h < 0.0 and max_h > 0.0, "La deriva orizzontale deve poter assumere valori sia positivi sia negativi")
